import{_ as p,a0 as o,w as r,s as d,I as a,x as n,a1 as l,A as i,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何編寫和使用自定義的 Shell 函數和函數庫 | LCTT x X-CMD","titleTemplate":false,"description":"如何編寫和使用自定義的 Shell 函數和函數庫 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何編寫和使用自定義的 Shell 函數和函數庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何編寫和使用自定義的 Shell 函數和函數庫 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170207 How To Write and Use Custom Shell Functions and Libraries","title":"如何編寫和使用自定義的 Shell 函數和函數庫","tag":"201703","desc":""},"relativePath":"201703/20170207 How To Write and Use Custom Shell Functions and Libraries.md","filePath":"[post].md"}'),h={name:"201703/20170207 How To Write and Use Custom Shell Functions and Libraries.md"};function u(c,s,g,b,k,m){const e=o("Link");return r(),d("div",null,[s[22]||(s[22]=a("h1",{id:"如何編寫和使用自定義的-shell-函數和函數庫",tabindex:"-1"},[n("如何編寫和使用自定義的 Shell 函數和函數庫 "),a("a",{class:"header-anchor",href:"#如何編寫和使用自定義的-shell-函數和函數庫","aria-label":"Permalink to “如何編寫和使用自定義的 Shell 函數和函數庫”"},"​")],-1)),a("p",null,[s[1]||(s[1]=n("在 Linux 系統下，Shell 腳本可以在各種不同的情形下幫到我們，例如展示信息，甚至 ",-1)),l(e,{href:"http://www.tecmint.com/using-shell-script-to-automate-linux-system-maintenance-tasks/"},{default:i(()=>[...s[0]||(s[0]=[n("自動執行特定的系統管理任務",-1)])]),_:1}),s[2]||(s[2]=n("，創建簡單的命令列工具等等。",-1))]),s[23]||(s[23]=t(`<p>在本指南中，我們將向 Linux 新手展示如何可靠地存儲自定義的 shell 腳本，解釋如何編寫 shell 函數和函數庫，以及如何在其它的腳本中使用函數庫中的函數。</p><h3 id="shell-腳本要存儲在何處" tabindex="-1">Shell 腳本要存儲在何處 <a class="header-anchor" href="#shell-腳本要存儲在何處" aria-label="Permalink to “Shell 腳本要存儲在何處”">​</a></h3><p>為了在執行你自己的腳本時不必輸入腳本所在位置的完整或絕對路徑，腳本必須被存儲在 <code>$PATH</code> 環境變量所定義的路徑裏的其中一個。</p><p>使用下面的命令可以查看你係統中的 <code>$PATH</code> 環境變量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $PATH</span></span>
<span class="line"><span>/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:/usr/games:/usr/local/games</span></span></code></pre></div><p>通常來説，如果在用户的家目錄下存在名為 <code>bin</code> 的目錄，你就可以將 shell 腳本存儲在那個目錄下，因為那個目錄會自動地被包含在用户的 <code>$PATH</code> 環境變量中（LCTT 譯註：在 Centos 6/7 下是這樣的，在 Debian 8 下不是這樣的，在 Ubuntu 16.04 下又是這樣的)。</p>`,6)),a("p",null,[s[4]||(s[4]=n("因此，在你的主目錄下創建 ",-1)),s[5]||(s[5]=a("code",null,"bin",-1)),s[6]||(s[6]=n(" 目錄吧（當然這裏也可以用來存儲 Perl、",-1)),l(e,{href:"http://www.tecmint.com/use-linux-awk-command-to-filter-text-string-in-files/"},{default:i(()=>[...s[3]||(s[3]=[n("Awk",-1)])]),_:1}),s[7]||(s[7]=n(" 或 Python 的腳本，或者其它程序）：",-1))]),s[24]||(s[24]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/bin</span></span></code></pre></div><p>接着，建立一個名為 <code>lib</code>（libraries 的簡寫）的目錄來存放你自己的函數庫。你也可以在其中存放其它編程語言的函數庫，如 C ，Python 等語言。在 <code>lib</code> 目錄下建立另一個名為 <code>sh</code> 的目錄，這個目錄將被用來存放你的 shell 函數庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir -p ~/lib/sh</span></span></code></pre></div><h3 id="創建你自己的-shell-函數和函數庫" tabindex="-1">創建你自己的 Shell 函數和函數庫 <a class="header-anchor" href="#創建你自己的-shell-函數和函數庫" aria-label="Permalink to “創建你自己的 Shell 函數和函數庫”">​</a></h3><p>一個 <code>shell 函數</code> 就是在腳本中能夠完成特定任務的一組命令。它們的工作原理與其他編程語言中的過程（LCTT 譯註：可能指的是類似 SQL 中的存儲過程之類的吧）、子例程、函數類似。</p><p>編寫一個函數的語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>函數名() { 一系列的命令 }</span></span></code></pre></div><p>( LCTT 校注：在函數名前可以加上 <code>function</code> 關鍵字，但也可省略不寫）</p><p>例如，你可以像下面那樣在一個腳本中寫一個用來顯示日期的函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>showDATE() {date;}</span></span></code></pre></div><p>每當你需要顯示日期時，只需調用該函數的函數名即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ showDATE</span></span></code></pre></div><p>簡單來説 shell 函數庫也是一個 shell 腳本，不過你可以在一個函數庫中僅存儲其它 shell 腳本中需要調用的函數。</p><p>下面展示的是在我的 <code>~/lib/sh</code> 目錄下一個名為 <code>libMYFUNCS.sh</code> 的庫函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash </span></span>
<span class="line"><span>#Function to clearly list directories in PATH </span></span>
<span class="line"><span>showPATH() { </span></span>
<span class="line"><span>oldifs=&quot;$IFS&quot;   #store old internal field separator</span></span>
<span class="line"><span>IFS=:              #specify a new internal field separator</span></span>
<span class="line"><span>for DIR in $PATH ;  do echo $DIR ;  done</span></span>
<span class="line"><span>IFS=&quot;$oldifs&quot;    #restore old internal field separator</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#Function to show logged user</span></span>
<span class="line"><span>showUSERS() {</span></span>
<span class="line"><span>echo -e “Below are the user logged on the system:\\n”</span></span>
<span class="line"><span>w</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#Print a user’s details </span></span>
<span class="line"><span>printUSERDETS() {</span></span>
<span class="line"><span>oldifs=&quot;$IFS&quot;    #store old internal field separator</span></span>
<span class="line"><span>IFS=:                 #specify a new internal field separator</span></span>
<span class="line"><span>read -p &quot;Enter user name to be searched:&quot; uname   #read username</span></span>
<span class="line"><span>echo &quot;&quot;</span></span>
<span class="line"><span>#read and store from a here string values into variables using : as  a  field delimiter</span></span>
<span class="line"><span>read -r username pass uid gid comments homedir shell &lt;&lt;&lt; &quot;$(cat /etc/passwd | grep   &quot;^$uname&quot;)&quot;</span></span>
<span class="line"><span>#print out captured values</span></span>
<span class="line"><span>echo  -e &quot;Username is            : $username\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s ID                 : $uid\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s GID              : $gid\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s Comments    : $comments\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s Home Dir     : $homedir\\n&quot;</span></span>
<span class="line"><span>echo  -e &quot;User&#39;s Shell             : $shell\\n&quot;</span></span>
<span class="line"><span>IFS=&quot;$oldifs&quot;         #store old internal field separator</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存文件並且給腳本添加執行權限。</p><h3 id="如何從函數庫中調用函數" tabindex="-1">如何從函數庫中調用函數 <a class="header-anchor" href="#如何從函數庫中調用函數" aria-label="Permalink to “如何從函數庫中調用函數”">​</a></h3><p>要使用某個 <code>lib</code> 目錄下的函數，首先你需要按照下面的形式 將包含該函數的函數庫導入到需要執行的 shell 腳本中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ . /path/to/lib </span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>$ source /path/to/lib</span></span></code></pre></div><p>（LCTT 譯註：第一行的 <code>.</code> 和路徑間<strong>必須</strong>是有空格的）</p><p>這樣你就可以像下面演示的那樣，在其它的腳本中使用來自 <code>~/lib/sh/libMYFUNCS.sh</code> 的 <code>printUSERDETS</code> 函數了。</p><p>在下面的腳本中，如果要打印出某個特定用户的詳細信息，你不必再一一編寫代碼，而只需要簡單地調用已存在的函數即可。</p><p>創建一個名為 <code>test.sh</code> 的新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash </span></span>
<span class="line"><span>#include lib</span></span>
<span class="line"><span>.  ~/lib/sh/libMYFUNCS.sh</span></span>
<span class="line"><span>#use function from lib</span></span>
<span class="line"><span>printUSERDETS</span></span>
<span class="line"><span>#exit script</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>保存這個文件，並使得這個腳本可被執行，然後運行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 755 test.sh</span></span>
<span class="line"><span>$ ./test.sh</span></span></code></pre></div>`,26)),a("p",null,[l(e,{href:"http://www.tecmint.com/wp-content/uploads/2017/02/Write-Shell-Functions.png"},{default:i(()=>[...s[8]||(s[8]=[a("img",{src:"http://www.tecmint.com/wp-content/uploads/2017/02/Write-Shell-Functions.png",alt:"Write Shell Functions"},null,-1)])]),_:1})]),s[25]||(s[25]=a("p",null,[a("em",null,"編寫 shell 函數")],-1)),s[26]||(s[26]=a("p",null,"在本文中，我們介紹了在哪裏可靠地存儲 shell 腳本，如何編寫自己的 shell 函數和函數庫，以及如何在一個普通的 shell 腳本中從函數庫中調用庫中的某些函數。",-1)),s[27]||(s[27]=a("p",null,"在之後，我們還會介紹一種相當簡單直接的方式來將 Vim 配置為一個編寫 Bash 腳本的 IDE（集成開發環境）。在那之前，記得要經常關注我們 ，如果能和我們分享你對這份指南的想法就更好了。",-1)),s[28]||(s[28]=a("hr",null,null,-1)),s[29]||(s[29]=a("p",null,"作者簡介：Aaron Kili 是一名 Linux 和 F.O.S.S 愛好者、一名未來的 Linux 系統管理員、web 開發者，目前是一名 TecMint 上的內容創造者，他喜歡計算機相關的工作，並且堅信知識的分享。",-1)),s[30]||(s[30]=a("hr",null,null,-1)),a("p",null,[s[10]||(s[10]=n("via: ",-1)),l(e,{href:"http://www.tecmint.com/write-custom-shell-functions-and-libraries-in-linux/"},{default:i(()=>[...s[9]||(s[9]=[n("http://www.tecmint.com/write-custom-shell-functions-and-libraries-in-linux/",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=n("作者：",-1)),l(e,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...s[11]||(s[11]=[n("Aaron Kili",-1)])]),_:1}),s[15]||(s[15]=n(" 譯者：",-1)),l(e,{href:"https://github.com/wcnnbdk1"},{default:i(()=>[...s[12]||(s[12]=[n("wcnnbdk1",-1)])]),_:1}),s[16]||(s[16]=n(" 校對：",-1)),l(e,{href:"https://github.com/FSSlc"},{default:i(()=>[...s[13]||(s[13]=[n("FSSlc",-1)])]),_:1})]),a("p",null,[s[19]||(s[19]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[17]||(s[17]=[n("LCTT",-1)])]),_:1}),s[20]||(s[20]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:i(()=>[...s[18]||(s[18]=[n("Linux中國",-1)])]),_:1}),s[21]||(s[21]=n(" 榮譽推出",-1))])])}const S=p(h,[["render",u]]);export{C as __pageData,S as default};
